package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func digiGame(a, b, r int) {
	if 2*r <= a && 2*r <= b {
		fmt.Println("First")
	} else {
		fmt.Println("Second")
	}
}

